import Navbar from "../components/navigation/Navbar";
import projects from "../data/projects";
import { Link } from "react-router-dom";

const ProjectFullPage = () => {
    return (
        <>
            <Navbar color="#ffffff" text_body="#000000" text_cv="#ffffff" bg_cv="#000000"/>
            <section>
                <div className="project_full_page">
                    {projects.map((element) => (
                        <Link
                            to={`/projects/${element.slug}`}
                        >
                            <div className="card_projects_full_page">
                                <img src={element.image} alt={element.slug}/>
                                <div className="title_projects_full_page">
                                    <p>{element.title}</p>
                                    <p>×</p>
                                    <p>{element.with}</p>
                                </div>
                            </div>
                        </Link>
                    ))}
                </div>
            </section>
        </>
    )
}

export default ProjectFullPage;
